You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

The exponent of matrix multiplication $\omega$ is the smallest number such that for any $\varepsilon > 0$, there exists an algorithm for multiplying $n \times n$ matrices using $O(n^{\omega + \varepsilon})$ arithmetic operations.

\begin{conjecture}\label{conj:skew}
Fix any $\varepsilon > 0$. If $S$ is skew corner-free, then $|S| \le O(n^{1+\varepsilon})$.
\end{conjecture}

\begin{restatable}{theorem}{main2}
	\label{thm:main2}
If the largest skew corner-free subset of $[n]^2$ has size $O(n^{4/3 - \varepsilon})$ for some $\varepsilon > 0$, then \cite[Conjecture 4.7]{cohn2005group} is false.
\end{restatable}

\begin{definition}
	A collection of triples of subsets $S_i, T_i, U_i$ of a group $G$ satisfy the simultaneous triple product property (or STPP for short) if
	\begin{enumerate}
		\item For each $i$, the sets $S_i, T_i, U_i$ satisfy the \emph{triple product property}: if $ss'^{-1}tt'^{-1}uu'^{-1}=I$ with $s, s' \in S_i, t,t' \in T_i, u,u' \in U_i$, then $s=s', t=t', u=u'$.
		\item Setting $S_i = A_iB_i^{-1}, T_j = B_jC_j^{-1}, U_k = C_kA_k^{-1}$, 
		\[ s_it_ju_k = I \iff i=j=k\]
		for all $s_i \in S_i, t_j \in T_j, u_k \in U_k$.
	\end{enumerate}
\end{definition}

\begin{theorem}\label{prop:stppbound}\cite[Theorem 5.5]{cohn2005group}
	If $S_i, T_i, U_i \subseteq G$ satisfy the STPP, then
	\[\sum_i (|S_i||T_i||U_i|)^{\omega/3} \le \sum d_i^\omega \]
	where $d_i$'s are the dimensions of the irreducible representations of $G$.
\end{theorem}

\begin{definition}
	We say that sets $(A_i, B_i)_{i=1}^n$ satisfy the simultaneous double product property (or SDPP for short) if 
	\begin{enumerate}
		\item For all $i$, $aa'^{-1} = bb'^{-1}$ only has the solution $a=a', b=b'$ for $a,a' \in A_i, b,b' \in B_i$,
		\item $a_i (a_j')^{-1}b_j(b_k')^{-1} = 1$ implies $i=k$, where $a_i \in A_i, a_j' \in A_j, b_j \in B_j, b_k' \in B_k$.
	\end{enumerate}
\end{definition}

\begin{conjecture}\cite[Conjecture 4.7]{cohn2005group}\label{conj:twofamilies}
	For arbitrarily large $n$, there exists an abelian group $G$ of order $n^{2-o(1)}$ and $n$ pairs of sets $A_i, B_i$ where $|A_i||B_i| > n^{2-o(1)}$ satisfy the SDPP.
\end{conjecture}

If $G$ is a finite group, we let $X_G$ denote the tripartite 3-uniform hypergraph with vertex parts $X_1 = X_2 = X_3 = G$, and where $(g_1, g_2, g_3)$ is a hyperedge (a \emph{triangle}) whenever $g_1g_2g_3=I$. In the event that $G$ is nonabelian, it is important that we fix some ordering on the parts of $X_G$ here. Recall that a 3-uniform hypergraph is said to be \emph{linear} if any two vertices are contained in at most one hyperedge. For example, $X_G$ is linear. The matrix multiplication hypergraph $M_{p,q,r}$ is defined to be the supporting hypergraph of the matrix multiplication tensor; i.e.~it is the hypergraph with parts $[p]\times [q], [q] \times [r], [r] \times [p]$, and where $((i,j), (k,l), (m,n))$ is a hyperedge if and only if $j=k, l=m, n=i$. If $X$ is a hypergraph, we sometimes write $E(X)$ for the set of hyperedges of $X$.

\begin{proposition}
There exist sets $S_i, T_i, U_i \subseteq G$, satisfying the STPP if and only if $X_G$ contains as an induced subhypergraph the disjoint union of $M_{|S_i|, |T_i|, |U_i|}$.
\end{proposition}

\begin{corollary}\label{cor:packingbarrier}
If $X_i,Y_i,Z_i$ satisfy the STPP in a group $G$ of order $n$, then at least one of $\sum |X_i||Y_i|, \sum |X_i||Z_i|, \sum |Y_i||Z_i|$ is at most $o(n)$.
\end{corollary}

\begin{corollary}\label{cor:removaltight}
There exists an absolute constant $C > 1$ such that if $X_i,Y_i,Z_i$ satisfy the STPP in $\Z_q^\ell$, then at least one of $\sum |X_i||Y_i|, \sum |X_i||Z_i|, \sum |Y_i||Z_i|$ is at most $(q/C)^\ell$.
\end{corollary}

\begin{proposition}\label{prop:extremalprob}
	Let $X$ be a linear tripartite hypergraph with parts of size $N$ such that any two vertices from different parts are incident to at most one common vertex in the third part. Then the number of triangles in $X$ is at most $N^{3/2}$. Furthermore, when $N$ is a square, an extremal example is the matrix multiplication hypergraph $M_{N^{1/2}}$.
\end{proposition}

\begin{definition}\label{def:trap}
	Let $A, B, C \subseteq G$. We call $(A,B,C)$ equilateral trapezoid-free if the subhypergraph of $X_G$ induced by $A \subseteq X_1,B\subseteq X_2,C \subseteq X_3$ satisfies the conditions of \Cref{prop:extremalprob}. Equivalently, $(A,B,C)$ is equilateral trapezoid-free if for any fixed $a' \in A , b' \in B , c'\in C$, the following systems of equations in the variables $a \in A, b \in B, c \in C$ each have at most one solution:
	\begin{align*}
		I&=a'bc=ab'c,\\
		I&=a'bc=abc',\\
		I&=ab'c=abc'.
	\end{align*}
	Let $\Val(G)$ be the maximum number of solutions to $abc=I$ over all equilateral trapezoid-free triples $(A,B,C)$. 
\end{definition}

\begin{proposition}\label{prop:stppval}
	Suppose that $X_G$ contains disjoint induced subhypergraphs $M_{n_i,m_i,p_i}$. Then, $\Val(G) \ge \sum_{i} n_im_ip_i$.
\end{proposition}

Throughout this section, we let $\Delta_{n+1} = \{(a,b,c) \in \Z_{\ge 0}^3: a+b+c=n\}$.

\begin{definition}\label{def:trapplane}
	Let $A, B, C \subseteq \{0, \ldots, n\}$. We call $(A,B,C)$ an equilateral trapezoid-free triple if for any fixed $a', b', c'$, the following systems of equations in the variables $a \in A, b \in B, c \in C$ each have at most one solution:
	\begin{align*}
		n&=a'+b+c=a+b'+c\\
		n&=a'+b+c=a+b+c'\\
		n&=a+b'+c=a+b+c'.
	\end{align*}
	Let $\Val(n)$ be the maximum number of solutions to $a+b+c=n$ over all equilateral trapezoid-free triples $(A,B,C)$. 
\end{definition}

\begin{proposition}\label{prop:resasonable}
	\begin{enumerate}
		\item $\Val(n) \ge \Val(n-1)$.
		\item $1+2 \cdot \Val(2n) \ge \Val(\Z_n) \ge \Val(\lfloor n/3 \rfloor)$.
		\item For $n \ge 6n'$, $\Val(\Z_n) \ge \Val(\Z_n')/2-1$
	\end{enumerate}

\end{proposition}

\begin{theorem}\label{thm:twofam43}
If \Cref{conj:twofamilies} is true, then for any $\varepsilon > 0$, $\Val(\Z_n) \ge O(n^{4/3-\varepsilon})$.
\end{theorem}

\begin{definition}\label{def:trifree}
	Let $A, B, C \subseteq \{0, \ldots, n\}$. We say that $(A,B,C)$ is triforce-free if there is no solution to
	\[a+b+c'=a+b'+c=a'+b+c=n\]
	with $a \neq a', b \neq b', c \neq c'$.
	We write $\Val(\triforce{0.4cm},n)$ for the maximum over all such $A,B,C$ of the number of solutions to $a+b+c=n$.
\end{definition}

\begin{definition}\label{def:skewcorners}
	We call $S \subseteq \Delta_n$ skew-corner free if for $(a,b,c), (a,b',c') \in S$, it holds that $(a+b - b', b'', c'') \notin S$ for all $b'', c''$, and this remains true after any permutation of the coordinates of $S$. 
\end{definition}

\begin{proposition}\label{prop:tridel}
The largest skew-corner free subset of $\Delta_{n+1}$ is at least $\Val(\triforce{0.4cm},n)$.
\end{proposition}

\begin{definition}\label{def:biskew}
We say $S \subset [n]^2$ is skew corner-free if it contains no configuration $(x,y), (x,y+d), (x+d, y')$ with $d \neq 0$.
\end{definition}

\begin{proposition}\label{prop:skewdel}
The largest skew corner-free subset of $[n]^2$ is at least as big as the largest skew corner-free subset of $\Delta_n$.
\end{proposition}


